parameters.jsCode:
const raw = $json.output || "";

const match = raw.match(/\{[\s\S]*\}/);

if (!match) {
  return [
    {
      json: {
        intent: "normal_chat",
        requested_intent: "normal_chat",
        ready_to_check: false,
        valid_booking: false,
        response_message: raw || "Please provide your appointment details."
      }
    }
  ];
}

try {
  const parsed = JSON.parse(match[0]);
  const errors = [];

  function convertTo24Hour(time) {
    time = String(time || "").trim();

    const amPmMatch = time.match(/^(\d{1,2}):(\d{2})\s?(AM|PM)$/i);

    if (amPmMatch) {
      let hour = parseInt(amPmMatch[1], 10);
      const minute = amPmMatch[2];
      const period = amPmMatch[3].toUpperCase();

      if (hour < 1 || hour > 12) return time;

      if (period === "PM" && hour !== 12) hour += 12;
      if (period === "AM" && hour === 12) hour = 0;

      return `${String(hour).padStart(2, "0")}:${minute}`;
    }

    return time;
  }

  function isMissing(value) {
    return (
      value === undefined ||
      value === null ||
      value.toString().trim() === ""
    );
  }

  function missingMessage(fields, actionText) {
    if (fields.length === 1) {
      return `Please provide your ${fields[0]} to ${actionText}.`;
    }

    const last = fields[fields.length - 1];
    const rest = fields.slice(0, -1);

    return `Please provide your ${rest.join(", ")} and ${last} to ${actionText}.`;
  }

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  const yyyyMmDdRegex = /^\d{4}-\d{2}-\d{2}$/;
  const hhMmRegex = /^([01]\d|2[0-3]):[0-5]\d$/;

  const requestedIntent = parsed.intent || "booking";

  // =====================================================
  // CANCELLATION FLOW
  // =====================================================
  if (requestedIntent === "cancel_appointment") {
    const requiredFields = ["email", "appointment_date"];

    const missingFields = requiredFields.filter(field => isMissing(parsed[field]));

    if (missingFields.length > 0) {
      return [
        {
          json: {
            ...parsed,
            intent: "normal_chat",
            requested_intent: "cancel_appointment",
            ready_to_check: false,
            valid_booking: false,
            valid_cancellation: false,
            missing_fields: missingFields,
            validation_errors: [],
            response_message: missingMessage(missingFields, "cancel the appointment")
          }
        }
      ];
    }

    parsed.email = parsed.email.toString().trim();
    parsed.appointment_date = parsed.appointment_date.toString().trim();
    parsed.doctor_name = parsed.doctor_name ? parsed.doctor_name.toString().trim() : "";
    parsed.department = parsed.department ? parsed.department.toString().trim() : "";

    if (!emailRegex.test(parsed.email)) {
      errors.push("Please provide a valid email address.");
    }

    if (!yyyyMmDdRegex.test(parsed.appointment_date)) {
      errors.push("Appointment date must be in YYYY-MM-DD format.");
    }

    const valid_cancellation = errors.length === 0;

    return [
      {
        json: {
          ...parsed,
          intent: valid_cancellation ? "cancel_appointment" : "normal_chat",
          requested_intent: "cancel_appointment",
          ready_to_check: valid_cancellation,
          valid_booking: false,
          valid_cancellation,
          validation_errors: errors,
          response_message: valid_cancellation
            ? "Cancellation details validated successfully."
            : errors[0]
        }
      }
    ];
  }

  // =====================================================
  // RESCHEDULE FLOW
  // =====================================================
  if (requestedIntent === "reschedule_appointment") {
    const requiredFields = [
      "email",
      "appointment_date",
      "new_appointment_date",
      "new_appointment_time"
    ];

    const missingFields = requiredFields.filter(field => isMissing(parsed[field]));

    if (missingFields.length > 0) {
      return [
        {
          json: {
            ...parsed,
            intent: "normal_chat",
            requested_intent: "reschedule_appointment",
            ready_to_check: false,
            valid_booking: false,
            valid_reschedule: false,
            missing_fields: missingFields,
            validation_errors: [],
            response_message: missingMessage(missingFields, "reschedule the appointment")
          }
        }
      ];
    }

    parsed.email = parsed.email.toString().trim();
    parsed.appointment_date = parsed.appointment_date.toString().trim();
    parsed.new_appointment_date = parsed.new_appointment_date.toString().trim();
    parsed.new_appointment_time = convertTo24Hour(parsed.new_appointment_time);

    parsed.doctor_name = parsed.doctor_name ? parsed.doctor_name.toString().trim() : "";
    parsed.department = parsed.department ? parsed.department.toString().trim() : "";
    parsed.new_doctor_id = parsed.new_doctor_id ? Number(parsed.new_doctor_id) : null;
    parsed.new_doctor_name = parsed.new_doctor_name ? parsed.new_doctor_name.toString().trim() : "";
    parsed.new_department = parsed.new_department ? parsed.new_department.toString().trim() : "";

    if (!emailRegex.test(parsed.email)) {
      errors.push("Please provide a valid email address.");
    }

    if (!yyyyMmDdRegex.test(parsed.appointment_date)) {
      errors.push("Current appointment date must be in YYYY-MM-DD format.");
    }

    if (!yyyyMmDdRegex.test(parsed.new_appointment_date)) {
      errors.push("New appointment date must be in YYYY-MM-DD format.");
    }

    if (!hhMmRegex.test(parsed.new_appointment_time || "")) {
      errors.push("Please select a valid new appointment time.");
    }

    if (
      yyyyMmDdRegex.test(parsed.new_appointment_date || "") &&
      hhMmRegex.test(parsed.new_appointment_time || "")
    ) {
      const newAppointmentDateTime = new Date(
        `${parsed.new_appointment_date}T${parsed.new_appointment_time}:00+05:30`
      );

      const now = new Date();

      if (isNaN(newAppointmentDateTime.getTime())) {
        errors.push("New appointment date/time is invalid.");
      } else if (newAppointmentDateTime <= now) {
        errors.push("New appointment cannot be in the past.");
      }
    }

    const valid_reschedule = errors.length === 0;

    return [
      {
        json: {
          ...parsed,
          intent: valid_reschedule ? "reschedule_appointment" : "normal_chat",
          requested_intent: "reschedule_appointment",
          ready_to_check: valid_reschedule,
          valid_booking: false,
          valid_reschedule,
          validation_errors: errors,
          response_message: valid_reschedule
            ? "Reschedule details validated successfully."
            : errors[0]
        }
      }
    ];
  }

  // =====================================================
  // BOOKING FLOW
  // =====================================================
  const requiredFields = [
    "patient_name",
    "email",
    "department",
    "doctor_id",
    "doctor_name",
    "appointment_date",
    "appointment_time",
    "reason"
  ];

  const fieldLabels = {
    patient_name: "patient name",
    email: "email address",
    department: "department",
    doctor_id: "doctor selection",
    doctor_name: "doctor name",
    appointment_date: "appointment date",
    appointment_time: "appointment time",
    reason: "health problem or reason for visit"
  };

  const missingFields = requiredFields.filter(field => isMissing(parsed[field]));

  const ready_to_check = missingFields.length === 0;

  if (!ready_to_check) {
    const readableMissing = missingFields.map(
      field => fieldLabels[field] || field
    );

    let response_message = "";

    if (readableMissing.length === 1) {
      response_message = `Please provide your ${readableMissing[0]}.`;
    } else if (readableMissing.length === 2) {
      response_message = `Please provide your ${readableMissing[0]} and ${readableMissing[1]}.`;
    } else {
      const allButLast = readableMissing.slice(0, -1);
      const last = readableMissing[readableMissing.length - 1];
      response_message = `Please provide your ${allButLast.join(", ")}, and ${last}.`;
    }

    return [
      {
        json: {
          ...parsed,
          intent: "normal_chat",
          requested_intent: "booking",
          ready_to_check: false,
          valid_booking: false,
          missing_fields: missingFields,
          missing_field_labels: readableMissing,
          validation_errors: [],
          response_message
        }
      }
    ];
  }

  if (!emailRegex.test(parsed.email || "")) {
    errors.push("Please provide a valid email address.");
  }

  if (parsed.phone && parsed.phone.toString().trim() !== "") {
    const phoneRegex = /^[0-9+\-\s]{7,15}$/;

    if (!phoneRegex.test(parsed.phone.toString().trim())) {
      errors.push("Please provide a valid phone number or leave it blank.");
    }
  }

  const doctorId = Number(parsed.doctor_id);

  if (!doctorId || doctorId <= 0) {
    errors.push("Please select a valid doctor.");
  }

  if (!yyyyMmDdRegex.test(parsed.appointment_date || "")) {
    errors.push("Appointment date must be in YYYY-MM-DD format.");
  }

  parsed.appointment_time = convertTo24Hour(parsed.appointment_time);

  if (!hhMmRegex.test(parsed.appointment_time || "")) {
    errors.push("Please select a valid appointment time.");
  }

  if (
    yyyyMmDdRegex.test(parsed.appointment_date || "") &&
    hhMmRegex.test(parsed.appointment_time || "")
  ) {
    const appointmentDateTime = new Date(
      `${parsed.appointment_date}T${parsed.appointment_time}:00+05:30`
    );

    const now = new Date();

    if (isNaN(appointmentDateTime.getTime())) {
      errors.push("Appointment date/time is invalid.");
    } else if (appointmentDateTime <= now) {
      errors.push("Appointments cannot be booked for past dates or times.");
    }
  }

  parsed.phone = parsed.phone ? parsed.phone.toString().trim() : "";
  parsed.email = parsed.email.toString().trim();
  parsed.patient_name = parsed.patient_name.toString().trim();
  parsed.department = parsed.department.toString().trim();
  parsed.doctor_name = parsed.doctor_name.toString().trim();
  parsed.appointment_date = parsed.appointment_date.toString().trim();
  parsed.appointment_time = parsed.appointment_time.toString().trim();
  parsed.reason = parsed.reason.toString().trim();

  const valid_booking = errors.length === 0;

  return [
    {
      json: {
        ...parsed,
        intent: valid_booking ? "booking" : "normal_chat",
        requested_intent: "booking",
        doctor_id: doctorId,
        ready_to_check,
        valid_booking,
        validation_errors: errors,
        response_message: valid_booking
          ? parsed.message || "Appointment details validated successfully."
          : errors[0]
      }
    }
  ];

} catch (error) {
  return [
    {
      json: {
        intent: "normal_chat",
        requested_intent: "normal_chat",
        ready_to_check: false,
        valid_booking: false,
        validation_errors: ["Invalid appointment data format."],
        response_message: "Invalid appointment data format."
      }
    }
  ];
}

