const bookingData = $('Prepare Final Booking Data').first().json;

const slotBooked = !!$json.appointment_id;

function getIndiaNow() {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: "Asia/Kolkata",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  }).formatToParts(new Date());

  const data = {};
  for (const part of parts) {
    data[part.type] = part.value;
  }

  return {
    today: `${data.year}-${data.month}-${data.day}`,
    currentMinutes: Number(data.hour) * 60 + Number(data.minute)
  };
}

function toMinutes(time) {
  const [h, m] = String(time).split(":").map(Number);
  return h * 60 + m;
}

const indiaNow = getIndiaNow();
const appointmentMinutes = toMinutes(bookingData.appointment_time);

const slotInPast =
  bookingData.appointment_date === indiaNow.today &&
  appointmentMinutes <= indiaNow.currentMinutes;

return [
  {
    json: {
      ...bookingData,
      slot_booked: slotBooked,
      slot_in_past: slotInPast,
      slot_valid: !slotBooked && !slotInPast,
      existing_appointment_id: $json.appointment_id || null,
      response_message: slotBooked
        ? "Sorry, this slot has already been booked. Please choose another available slot."
        : slotInPast
          ? "Sorry, this time has already passed today. Please choose a future slot."
          : "Slot is available."
    }
  }
];

const data = $input.first().json;

const otp = Math.floor(100000 + Math.random() * 900000).toString();

return [
  {
    json: {
      ...data,
      otp,
      action_type: data.action_type || data.intent || "booking",
      otp_expires_at: new Date(Date.now() + 10 * 60 * 1000).toISOString(),
      otp_verified: false,
      otp_status: "awaiting_otp"
    }
  }
];

