      otp_verified_at: otpValid
        ? new Date().toISOString()
        : null
    }
  }
];

const input =
  $json.response ||
  $json.chatInput ||
  $json.message ||
  "";

const text = String(input).trim().toLowerCase();

const otpMatch = text.match(/\b\d{6}\b/);

const resendRequested =
  text.includes("resend") ||
  text.includes("send again") ||
  text.includes("new otp") ||
  text.includes("resend otp");

return [
  {
    json: {
      ...$json,

      retry_input: input,

      intent: resendRequested
        ? "resend_otp"
        : otpMatch
          ? "verify_otp"
          : "unknown",

      otp: otpMatch
        ? otpMatch[0]
        : "",

      resend_requested: resendRequested
    }
  }
];

